/// <summary>
/// CB626_TMSEngineSOPackingSlip
/// Class responsible for populating the TMS engine temp table (calculation table) for delivery note
/// </summary>
final class METTMSEngineLinesTmpBuilder_PackingSlip extends METTMSEngineLinesTmpBuilder
{    
    METShipmentId shipmentId;
    METSalesOrderShipmentLoadLines salesOrderShipmentLoadLinesQueryRun;
    METWMSPicklistNumber wmsPicklistNumber;

}

Method.Source:
/// <summary>
/// New method
/// </summary>
/// <param name = "_salesTable">SalesTable record</param>
/// <param name = "_shipmentId">SO finalisation shipment id</param>
/// <param name = "_wmsPicklistNumber">AIS WMS picking list number</param>
void new(SalesTable _salesTable, METShipmentId _shipmentId, METWMSPicklistNumber _wmsPicklistNumber)
{        
    shipmentId = _shipmentId;
    wmsPicklistNumber = _wmsPicklistNumber;

    this.init(_salesTable);
}

/// <summary>
/// Manages the lineShipQty variable
/// </summary>
/// <param name = "_salesLine">Sales order line</param>
/// <returns>return shipment line picked qty. Could be different from the picked qty sent to Dallas during extraction</returns>
protected SalesOrderedQty lineShipQty(SalesLine   _salesLine)
{
    // TODO the PickedQty should be in the salesUOM. Currently a bug as it is in inventory unit.
    UnitOfMeasureSymbol inventUOM = _salesLine.inventTable().inventUnitId();
    Qty ret;
    // convert the PickedQty from inventory UOM to Sales UOM
    if (inventUOM == _salesLine.SalesUnit)
    {
        ret = salesOrderShipmentLoadLinesQueryRun.PickedQty;
    }
    else
    {
        ret = EcoResProductUnitConverter::convertGivenUnitSymbolsForReleasedProduct(
                        _salesLine.ItemId,
                        _salesLine.InventDimId,
                        salesOrderShipmentLoadLinesQueryRun.PickedQty,
                        inventUOM,
                        _salesLine.SalesUnit);
    }

    return ret;
}

/// <summary>
/// CCR only applies to CB626
/// </summary>
/// <param name = "_salesLine">Sales order line</param>
/// <returns>Yes if supplier warehouse is CCR or pick director; otherwise, false.</returns>
protected NoYes setSuppWhsHasCCR(SalesLine _salesLine)
{
    NoYes           ret = NoYes::No;

    // For CB626 set CCR if the supplying WH has CCR or pick director
    if (inventLocation.METCCR || inventLocation.METPickDirector)
    {        
        // If we can't find it then set SuppWhsHasCCR to No so that the default behaviour without CCR applies
        if (METCCRTable::existSalesItemInventLocationIdWMSPickList(_salesLine.SalesId,
                                                                   _salesLine.ItemId, 
                                                                   inventLocation.InventLocationId,
                                                                   wmsPicklistNumber))
        {
            ret = NoYes::Yes;

            // set hasCCR if at least one line in temp table has SuppWhsHasCCR = Yes
            if (!hasCCR)
            {
                hasCCR = true;
            }
        }
    }

    return ret;
}

/// <summary>
/// Initialise the sales order line query
/// </summary>
/// <returns><c>Query</c> object</returns>
protected Query initQuery()
{
    Query query = super();

    // extend the query to add a link to salesOrderShipmentLoadLines so that we can get the new PickedQty instead of salesLine.SalesQty
    QueryBuildDataSource qbds = query.dataSourceTable(tableNum(SalesLine));
    QueryBuildDataSource qbdsShipmentLines = qbds.addDataSource(tableNum(METSalesOrderShipmentLoadLines));
    qbdsShipmentLines.joinMode(JoinMode::InnerJoin);
    qbdsShipmentLines.addLink(fieldNum(SalesLine, InventTransId), fieldNum(METSalesOrderShipmentLoadLines, InventTransId));

    // filter shipment lines for the shipment being confirmed
    qbdsShipmentLines.addRange(fieldNum(METSalesOrderShipmentLoadLines, ShipmentId)).value(queryValue(shipmentId));

    return query;
}

/// <summary>
/// Get tables from _queryRun object used to fill the temp table
/// </summary>
/// <param name = "_queryRun"><c>QueryRun</c> object used to fill the temp table</param>
/// <returns>Container of records from the <c>QueryRun</c> object</returns>
protected SalesLine getTablesQueryRun(QueryRun _queryRun)
{
    // call the super to get the SalesLine record
    SalesLine ret = super(_queryRun);

    // get the METSalesOrderShipmentLoadLines record from the queryRun object, specific to PackingSlip
    salesOrderShipmentLoadLinesQueryRun = _queryRun.get(tableNum(METSalesOrderShipmentLoadLines));

    return ret;
}
